import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }

    // fuzzed parameter: a 4-byte interface id
    function testFuzz_property(bytes4 interfaceId) public {
        // no restrictive assumptions; accept any 4-byte value
        // Call supportsInterface and capture whether it returns or reverts
        bool ok;
        bool ret;
        try c.supportsInterface(interfaceId) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        // The universal property: for the reference implementation,
