        // the reference never reverts from supportsInterface, so ok must be true for all inputs.
        bytes4 erc165Id = type(IERC165).interfaceId;
        bool expected = (interfaceId == erc165Id);
        // The single assertion for the test: reference returns as expected for all inputs.
        // This will pass on the correct contract and fail for the mutant when the fuzzer picks
        // interfaceId == type(IERC165).interfaceId (mutant inverts return value).
        assertTrue(ok && (ret == expected));
    }
