        // call supportsInterface and observe its return without reverting
        bool ok;
        try c.supportsInterface(iface) returns (bool r) {
            ok = r;
        } catch {
            ok = false; // but supportsInterface in both versions does not revert, safe fallback
        }

        // The intended universal property: reference returns true iff iface == type(IERC165).interfaceId
