        // compute IERC165 interface id by using the function selector of supportsInterface
        // IERC165 interfaceId is well-known as type(IERC165).interfaceId, but we cannot reference that
        // directly here without importing interface; instead derive it as selector of supportsInterface signature
        // which is bytes4(keccak256("supportsInterface(bytes4)")) — equals IERC165 interface id for this contract's supportsInterface
        ierc165 = bytes4(keccak256("supportsInterface(bytes4)"));

        if (iface == ierc165) {
            // For reference contract, supportsInterface(ierc165) must be true.
